function drawMap(){mctx.clearRect(0,0,300,232);mctx.fillStyle='#28382b';mctx.fillRect(0,0,300,232);mctx.strokeStyle='#4b583f';mctx.lineWidth=2;for(let i=0;i<5;i++){mctx.beginPath();mctx.moveTo(i*78-10,0);mctx.lineTo(i*70+20,232);mctx.stroke()}mctx.strokeStyle='#a99a6a';mctx.lineWidth=5;mctx.beginPath();mctx.moveTo(15,188);mctx.quadraticCurveTo(85,160,119,124);mctx.quadraticCurveTo(162,82,275,51);mctx.stroke();mctx.strokeStyle='#ddd0a055';mctx.lineWidth=1;mctx.stroke();for(const t of targets){if(!t.alive)continue;let x=t.x/world.w*300,y=t.y/world.h*232;if(t.type==='wolf'||t.type==='boar'){mctx.fillStyle=t.type==='wolf'?'#d67955':'#bf995c';mctx.beginPath();mctx.arc(x,y,2.4,0,Math.PI*2);mctx.fill()}else{mctx.fillStyle=t.type==='fiber'?'#8fbd70':t.type==='ore'?'#baa587':'#d6d07a';mctx.fillRect(x-1,y-1,2,2)}}mctx.fillStyle='#f6d990';mctx.strokeStyle='#161a13';mctx.lineWidth=2;mctx.beginPath();mctx.arc(player.x/world.w*300,player.y/world.h*232,4.2,0,Math.PI*2);mctx.fill();mctx.stroke()}
let moveTarget=null;
function update(dt){elapsed+=dt;player.attackCd=Math.max(0,player.attackCd-dt);player.attackAnim=Math.max(0,player.attackAnim-dt);player.invuln=Math.max(0,player.invuln-dt);player.energy=Math.min(player.maxEnergy,player.energy+4*dt);for(let k in skills){let s=skills[k];if(s.cd>0){s.cd=Math.max(0,s.cd-dt);let el=document.querySelector(`[data-skill="${k}"]`);if(el){el.querySelector('.cool').textContent=s.cd.toFixed(1);if(s.cd===0)el.classList.remove('oncool')}}}
let mx=0,my=0;if(keys.w||keys.ArrowUp)my--;if(keys.s||keys.ArrowDown)my++;if(keys.a||keys.ArrowLeft)mx--;if(keys.d||keys.ArrowRight)mx++;if(joyVector.x||joyVector.y){mx+=joyVector.x;my+=joyVector.y}if(mx||my){let l=Math.hypot(mx,my);player.x=clamp(player.x+mx/l*player.speed*dt,30,world.w-30);player.y=clamp(player.y+my/l*player.speed*dt,30,world.h-30);moveTarget=null}else if(moveTarget){if(dist(player,moveTarget)<8)moveTarget=null;else moveToWorld(moveTarget,dt)}
for(const t of targets){if(!t.alive||!(t.type==='wolf'||t.type==='boar'))continue;t.hit=Math.max(0,t.hit-dt);t.attack-=dt;let d=dist(player,t);if(d<215){if(d>43){let dx=(player.x-t.x)/d,dy=(player.y-t.y)/d;t.x+=dx*52*dt;t.y+=dy*52*dt}else if(t.attack<=0&&player.invuln<=0){t.attack=1.5+rand();player.hp=Math.max(0,player.hp-(t.type==='wolf'?8:11));player.invuln=.45;floating.push({x:player.x,y:player.y-28,text:'−'+(t.type==='wolf'?8:11),life:.7,color:'#f08b75'});if(player.hp<=0&&!gameOver){gameOver=true;showDeath()}}}else{t.x+=Math.sin(elapsed*.6+t.phase)*5*dt;t.y+=Math.cos(elapsed*.45+t.phase)*4*dt}}
nearby=nearest(['fiber','ore','herbs'],66);let interact=document.getElementById('interact');if(nearby){interact.textContent=`[ E ]  GATHER ${nearby.type.toUpperCase()}`;interact.style.display='block'}else interact.style.display='none';updateHUD();
camX=clamp(player.x-W/2,0,world.w-W);camY=clamp(player.y-H/2,0,world.h-H);if(W>world.w)camX=-(W-world.w)/2;if(H>world.h)camY=-(H-world.h)/2;
}
function render(dt){ctx.setTransform(dpr,0,0,dpr,0,0);drawGround(camX,camY);drawDecor();let items=targets.filter(t=>t.alive&&(t.type==='fiber'||t.type==='ore'||t.type==='herbs')).map(t=>({y:t.y,draw:()=>drawResource(t)}));for(const t of targets)if(t.alive&&(t.type==='wolf'||t.type==='boar'))items.push({y:t.y,draw:()=>drawCreature(t)});items.push({y:player.y,draw:drawPlayer});items.sort((a,b)=>a.y-b.y);for(const i of items)i.draw();drawParticles(dt);drawMap()}
function frame(ts){let dt=Math.min(.04,(ts-last)/1000||0);last=ts;if(!modalOpen&&!gameOver)update(dt);render(dt);requestAnimationFrame(frame)}requestAnimationFrame(frame);

